  test("AC-accessibility Product detail page passes accessibility checks", async ({ page }) => {
    await test.step("Given I navigate to the product detail page", async () => {
      await page.goto("/product/1");
    });

    await test.step("Then the page passes axe accessibility checks", async () => {
      const { default: AxeBuilder } = await import("@axe-core/playwright");
      const axeResults = await new AxeBuilder({ page })
        .include("app-product-detail, [data-test='product-detail'], main")
        .withTags(["wcag2a", "wcag2aa"])
        .analyze();
      expect(
        axeResults.violations.map((v) => v.id).sort(),
        `axe violations: ${JSON.stringify(axeResults.violations, null, 2)}`
      ).toEqual([]);
